function parseRequirements(value){if(!value)return{};if(typeof value==='object')return value;try{return JSON.parse(value)||{}}catch{return{}}}
function normalizePlatformDemand(d){const requirements=parseRequirements(d.requirementsJson);return {id:d.id,externalId:d.externalId||'',source:d.source||'platform',persisted:true,name:d.name,projectTypeId:d.projectTypeId||'',area:d.area,stage:d.stage||'Triagem',step:0,history:[],objective:d.objective||'',solution:d.solution||'',benefit:d.benefit||'',risk:d.risk||'',cost:Number(d.estimatedCost)||0,hours:Number(d.estimatedHours)||0,impact:d.impact||'Médio',projectPrioritized:d.projectPrioritized===true,prioritizationDate:d.prioritizationDate||'',approvingDirector:d.approvingDirector||'',requesterName:d.requesterName||'',requesterEmail:d.requesterEmail||'',sourceStatus:d.sourceStatus||'',sourceEntity:d.sourceEntity||'',sourceCategory:d.sourceCategory||'',sourceOpenedAt:d.sourceOpenedAt||'',requirements,...requirements}}
