const storedDemands=Array.isArray(window.platformDemands)?window.platformDemands.map(normalizePlatformDemand):[],storedGlpiIds=new Set(storedDemands.filter(d=>d.source==='glpi').map(d=>String(d.externalId))),snapshotTickets=Array.isArray(window.glpiViabilityDemands?.tickets)?window.glpiViabilityDemands.tickets:[];
