const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});const progress=p=>{const project=projects.find(x=>x.id===p);if(project?.progressImported!=null)return project.progressImported;return Math.round(tasks.filter(t=>t.p===p).reduce((a,t)=>a+t.state/3,0)/Math.max(1,tasks.filter(t=>t.p===p).length)*100)};const hours=p=>tasks.filter(t=>t.p===p).reduce((a,t)=>a+(t.actual||0),0);const badge=s=>`<span class="badge ${/Atras|Rejeit|Inviável/.test(s)?'red':/Atenção|Aprova|Triagem|Suspenso/.test(s)?'amber':/planej|Estudo|Backlog/.test(s)?'blue':''}">${esc(s)}</span>`;
function projectIsPrioritized(project){return project?.projectPrioritized===true||project?.projectPrioritized===1||project?.projectPrioritized==='true'}
function prioritizationDateLabel(value){return value?new Date(value+'T12:00:00').toLocaleDateString('pt-BR'):'Data não informada'}
