async function setProjectTypeForProject(select,projectId){const project=projects.find(item=>item.id===Number(projectId)),previous=project?.projectTypeId;if(!project||!select.value)return;project.projectTypeId=Number(select.value);project.type=projectTypeName(project.projectTypeId);const response=await fetch('/api/projects',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({id:project.dbId,projectTypeId:project.projectTypeId})}),result=await response.json();if(!response.ok){project.projectTypeId=previous;project.type=projectTypeName(previous,project.type);select.value=previous||'';toast(result.error||'Não foi possível salvar o tipo do projeto.');return}render();toast('Tipo do projeto salvo.')}
function toast(s){document.querySelector('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=s;document.body.append(el);setTimeout(()=>el.remove(),4500)}
function nav(v){view=v;mobileMenuOpen=false;render()}
function toggleMobileMenu(force){mobileMenuOpen=typeof force==='boolean'?force:!mobileMenuOpen;document.querySelector('.sidebar')?.classList.toggle('mobile-open',mobileMenuOpen);document.querySelector('.nav-scrim')?.classList.toggle('visible',mobileMenuOpen);document.querySelector('.mobile-menu-toggle')?.setAttribute('aria-expanded',String(mobileMenuOpen));document.body.classList.toggle('menu-open',mobileMenuOpen)}
function heading(title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">GESTÃO DE PROJETOS · TI</div><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`}
function stat(label,val,foot){return `<div class="stat"><div class="muted">${label}</div><strong>${val}</strong><small>${foot}</small></div>`}
function projectSelect(val,fn,all=false){return `<select aria-label="Selecionar projeto" onchange="${fn}">${all?'<option value="0">Todos os projetos</option>':''}${projects.map(p=>`<option value="${p.id}" ${+val===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`}
