function render(){ $('#app').innerHTML=`<div class="shell"><aside class="sidebar ${mobileMenuOpen?'mobile-open':''}" id="workspace-navigation"><div class="sidebar-mobile-head"><div class="brand">RAÍZES E RIQUEZAS<small>GESTÃO INTEGRADA DE PROJETOS</small></div><button class="sidebar-close" aria-label="Fechar menu" onclick="toggleMobileMenu(false)">✕</button></div><div class="navlabel">ESPAÇO DE TRABALHO</div><nav>${menu.map(([id,icon,label])=>`<button class="nav ${view===id?'active':''}" onclick="nav('${id}')"><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav><footer><span class="avatar">${esc(identityInitials)}</span><br>${esc(currentIdentity.displayName)}<br><span>${esc(currentIdentity.email)}</span></footer></aside><button class="nav-scrim ${mobileMenuOpen?'visible':''}" aria-label="Fechar menu" onclick="toggleMobileMenu(false)"></button><main><header class="topbar"><div class="topbar-title"><button class="mobile-menu-toggle" aria-label="Abrir menu" aria-controls="workspace-navigation" aria-expanded="${mobileMenuOpen}" onclick="toggleMobileMenu()"><span></span><span></span><span></span></button><span>Raízes e Riquezas <span class="muted"> / ${window.tenantInfo?esc(window.tenantInfo.name):'Gestão Integrada de Projetos'}</span></span></div><div>${window.tenantSlug?`<span class="badge">${esc(window.tenantInfo?.name||window.tenantSlug)}</span>`:'<span class="demo">BASE LOCAL · DADOS CONSOLIDADOS</span>'}<span class="avatar">${esc(identityInitials)}</span><a class="logout" href="${projectPath('/api/auth/logout')}">Sair</a></div></header><div class="content">${({portfolio,dashboards,projeto,demandas,aprovacoes,gantt,kanban,comparativo,recursos,administracao})[view]()}</div></main></div>`;document.body.classList.toggle('menu-open',mobileMenuOpen);applyResponsiveTableLabels()}
function applyResponsiveTableLabels(){document.querySelectorAll('table.responsive-table').forEach(table=>{const labels=[...table.querySelectorAll('thead th')].map(cell=>cell.textContent.trim());table.querySelectorAll('tbody tr').forEach(row=>[...row.children].forEach((cell,index)=>{if(cell.tagName==='TD'&&!cell.hasAttribute('colspan'))cell.dataset.label=labels[index]||''}))})}
function portfolio(){let shown=projects.filter(p=>p.name.toLowerCase().includes(filter.toLowerCase())&&(area==='Todas as áreas'||p.area===area));return heading('Portfólio de projetos','Uma visão da carteira, das entregas e da capacidade da equipe.',`<button class="primary" onclick="nav('gantt')">Visualizar cronograma ↗</button>`)+`<div class="stats">${stat('Projetos na carteira',projects.length,'Carteira demonstrativa · 2026')}${stat('Em execução',projects.filter(p=>p.status==='Em execução').length,'Projetos com atividades em curso')}${stat('Precisam de atenção',projects.filter(p=>p.risk!=='No prazo').length,'Riscos de prazo identificados')}${stat('Aprovações pendentes',demands.filter(d=>d.stage==='Aprovações').length,'Demandas aguardando decisão')}</div><section class="panel"><div class="panelhead"><h2>Carteira de projetos <span class="muted"> / ${shown.length}</span></h2><div class="toolbar"><input aria-label="Buscar projeto" placeholder="Buscar projeto…" value="${esc(filter)}" onchange="filter=this.value;render()"><select aria-label="Filtrar área" onchange="area=this.value;render()">${['Todas as áreas','Operações','Financeiro','Suprimentos'].map(a=>`<option ${a===area?'selected':''}>${a}</option>`).join('')}</select></div></div><div class="tablewrap"><table class="responsive-table"><thead><tr><th>Projeto / área</th><th>Responsável</th><th>Fase</th><th>Progresso</th><th>Prazo</th><th></th></tr></thead><tbody>${shown.map(p=>`<tr><td><button class="projecttitle" onclick="openProject(${p.id})">${esc(p.name)}</button><span class="sub">PRJ-${String(p.id).padStart(3,'0')} · ${p.area}</span></td><td>${people[p.owner]}</td><td>${badge(p.status)}</td><td>${progress(p.id)}%<div class="progress"><i style="width:${progress(p.id)}%"></i></div></td><td>${badge(p.risk)}</td><td><button aria-label="Abrir ${esc(p.name)}" onclick="openProject(${p.id})">↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum projeto encontrado.</td></tr>'}</tbody></table></div></section><div class="split"><section class="panel"><div class="panelhead"><h2>Próximas decisões</h2><button onclick="nav('aprovacoes')">Ver aprovações</button></div>${demands.map(d=>`<div class="row"><div><p>${esc(d.name)}</p><span class="sub">${demandReference(d)} · ${esc(d.area)}</span></div>${badge(d.stage)}</div>`).join('')}</section><section class="panel"><div class="panelhead"><h2>Capacidade dos keyusers</h2><button onclick="nav('recursos')">Detalhar</button></div><div class="pad" style="padding-top:0"><div class="muted">Semana de 14 a 18 de setembro</div><div class="capacity"><i style="width:46%"></i><b style="width:44%"></b></div><div class="legend"><span>Projetos: 92h</span><span>Sustentação: 88h</span><span>Saldo: 20h</span></div><p class="muted">1 profissional com alocação acima da capacidade.</p></div></section></div>`}
function openProject(id){selected=id;view='projeto';render()}
function ganttRow(label,start,end,pct=0,type='',baseEnd=end){return `<div class="grow"><div class="glabel">${label}</div><div class="track">${type==='milestone'?`<span class="diamond" style="left:${start}%" title="Marco"></span>`:`<div class="bar ${type}" style="left:${start}%;width:${Math.max(1,end-start)}%" title="Progresso: ${pct}%"><i style="width:${pct}%"></i><span>${pct}%</span></div><div class="baseline" style="left:${start}%;width:${Math.max(1,baseEnd-start)}%" title="Linha de base"></div>`}</div></div>`}
function gantt(){const p=projects.find(p=>p.id===selected),ts=tasks.filter(t=>t.p===selected);let rows='';if(ganttMode==='global') rows=projects.map(p=>ganttRow(`<button class="projecttitle" onclick="openProject(${p.id})">${esc(p.name)}</button><span class="sub">${p.area} · ${p.risk}</span>`,p.start,p.end,progress(p.id),'',p.risk==='Atrasado'?p.end-8:p.end)).join('');else {rows=ganttRow(`<b>${esc(p.name)}</b>`,p.start,p.end,progress(p.id));const groups=[...new Set(ts.map(t=>groupMode==='sprints'?'Sprint '+t.sprint:t.delivery))];for(let i=0;i<groups.length;i++){let g=groups[i],children=ts.filter(t=>(groupMode==='sprints'?'Sprint '+t.sprint:t.delivery)===g),key=p.id+g;rows+=ganttRow(`<button class="projecttitle" onclick="toggleGroup('${key}')">${collapsed.has(key)?'▸':'▾'} ${esc(g)}</button><span class="sub">${groupMode==='sprints'?'Ciclo de execução':'Fase / entrega'} · ${children.length} atividades</span>`,Math.min(...children.map(t=>t.start)),Math.max(...children.map(t=>t.end)),Math.round(children.reduce((a,t)=>a+t.state/3,0)/children.length*100),'sprint');if(!collapsed.has(key))rows+=children.map(t=>ganttRow(`<button class="projecttitle" style="padding-left:15px;font-weight:400" onclick="editTask(${t.id})">${esc(t.name)}</button><span class="sub" style="padding-left:15px">${people[t.person]} · ${states[t.state]}</span>`,t.start,t.end,Math.round(t.state/3*100))).join('');}rows+=ganttRow('◆ Aceite e encerramento',p.end,p.end,0,'milestone');}return heading('Cronograma de projetos','Do portfólio às entregas. Selecione um projeto para explorar sua estrutura.')+`<div class="tabs"><button class="${ganttMode==='global'?'active':''}" onclick="ganttMode='global';render()">Gantt Global</button><button class="${ganttMode==='individual'?'active':''}" onclick="ganttMode='individual';render()">Gantt Individual</button></div><section class="panel"><div class="panelhead"><h2>${ganttMode==='global'?'Todos os projetos':'Estrutura do projeto'}</h2><div class="toolbar">${ganttMode==='individual'?projectSelect(selected,'selected=+this.value;render()')+`<select aria-label="Agrupar cronograma" onchange="groupMode=this.value;render()"><option value="estrutura" ${groupMode==='estrutura'?'selected':''}>Por fases e entregas</option><option value="sprints" ${groupMode==='sprints'?'selected':''}>Por sprints</option></select>`:''}<span class="badge">2º semestre · 2026</span></div></div><div class="gantt"><div class="ganttgrid"><div class="ghead"><div>PROJETO / ESTRUTURA</div><div class="months">${['JUL','AGO','SET','OUT','NOV','DEZ'].map(m=>`<span>${m}</span>`).join('')}</div></div>${rows}</div></div><div class="gfoot">Verde: progresso por status · Linha cinza: planejamento original · ◆ Marco de aceite. Clique em uma atividade para editar.</div></section>${ganttMode==='individual'?`<div class="split"><section class="panel pad"><h2>Planejamento do projeto</h2><p>${badge(p.status)} ${badge(p.risk)}</p><p class="muted">Responsável: ${people[p.owner]}<br>Modelo: híbrido · Governança PMBOK e execução ágil</p><button onclick="kanbanProject='${p.id}';nav('kanban')">Abrir Kanban deste projeto →</button></section><section class="panel pad"><h2>Critério de entrega</h2><p class="muted">Homologação com os keyusers, validação pelo solicitante e registro do aceite para encerramento.</p><p class="mini">Neste protótipo, dependências e reprogramação automática ainda não são calculadas.</p></section></div>`:''}`}
function toggleGroup(k){collapsed.has(k)?collapsed.delete(k):collapsed.add(k);render()}
function kanban(){let ts=tasks.filter(t=>kanbanProject==='0'||t.p===+kanbanProject);return heading('Kanban de execução','Atividades compartilhadas com o Gantt e os indicadores.',`<button class="primary" onclick="editTask()">+ Nova atividade</button>`)+`<div class="toolbar" style="margin-bottom:22px">${projectSelect(kanbanProject,'kanbanProject=this.value;render()',true)}<span class="muted">${ts.length} atividades · arraste os cartões entre as colunas</span></div><div class="kanban">${states.map((s,i)=>`<section class="column kanban-dropzone" data-state="${i}" ondragover="allowTaskDrop(event)" ondragleave="leaveTaskDrop(event)" ondrop="dropTask(event,${i})"><h3>${s}<span class="muted">${ts.filter(t=>t.state===i).length}</span></h3>${ts.filter(t=>t.state===i).map(t=>`<article class="task draggable-task" draggable="true" ondragstart="startTaskDrag(event,${t.id})" ondragend="endTaskDrag(event)"><span class="drag-handle" aria-hidden="true">⋮⋮</span><span class="badge">Sprint ${t.sprint}</span><h3><button class="projecttitle" onclick="editTask(${t.id})">${esc(t.name)}</button></h3><p class="muted">${projects.find(p=>p.id===t.p).name}</p><span class="sub">${people[t.person]} · ${t.plan}h previstas / ${t.actual}h realizadas</span><div class="row"><select aria-label="Status de ${esc(t.name)}" onchange="moveTask(${t.id},+this.value)">${states.map((s,n)=>`<option value="${n}" ${n===i?'selected':''}>${s}</option>`).join('')}</select><button aria-label="Editar atividade" onclick="editTask(${t.id})">↗</button></div></article>`).join('')||'<p class="muted">Solte uma atividade nesta coluna.</p>'}</section>`).join('')}</div>`}
let draggedTaskId=null;
function startTaskDrag(event,id){draggedTaskId=id;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(id));requestAnimationFrame(()=>event.currentTarget.classList.add('dragging'))}
function allowTaskDrop(event){event.preventDefault();event.dataTransfer.dropEffect='move';event.currentTarget.classList.add('drop-target')}
function leaveTaskDrop(event){if(!event.currentTarget.contains(event.relatedTarget))event.currentTarget.classList.remove('drop-target')}
function dropTask(event,state){event.preventDefault();const id=Number(event.dataTransfer.getData('text/plain')||draggedTaskId);event.currentTarget.classList.remove('drop-target');if(Number.isInteger(id)&&tasks.some(t=>t.id===id))moveTask(id,state)}
function endTaskDrag(event){event.currentTarget.classList.remove('dragging');document.querySelectorAll('.kanban-dropzone.drop-target').forEach(column=>column.classList.remove('drop-target'));draggedTaskId=null}
async function moveTask(id,state){const task=tasks.find(t=>t.id===id);if(!task||task.state===state)return;const previous=task.state;task.state=state;render();if(task.dbId&&typeof persistProjectItem==='function'&&!(await persistProjectItem(task))){task.state=previous;render();toast('Não foi possível salvar o novo status.');return}toast(`Atividade movida para ${states[state]}. Kanban, Gantt e portfólio atualizados.`)}
function modal(title,body){document.querySelector('dialog')?.remove();let d=document.createElement('dialog');d.className='app-dialog';d.innerHTML=`<header><h2>${title}</h2><button aria-label="Fechar" onclick="this.closest('dialog').close()">✕</button></header><div class="dialog-body">${body}</div>`;document.body.append(d);d.showModal()}
function roleLabel(role){return ({project_coordinator:'Coordenador de Projetos',it_director:'Diretor de TI',project_analyst:'Analista de Projetos',keyuser:'Keyuser',requester:'Solicitante',area_manager:'Gerente/Diretor da área',viewer:'Consulta'})[role]||role}
function administracao(){return heading('Administração','Gerencie usuários, recursos e os cadastros usados no planejamento.',`<div class="toolbar"><button onclick="editProjectType()">+ Novo tipo</button><button class="primary" onclick="editPlatformUser()">+ Novo usuário</button></div>`)+projectTypeAdministration()+`<section class="panel"><div class="panelhead"><div><h2>Usuários cadastrados</h2><span class="sub">${platformUsers.length} contas · o primeiro acesso exige troca da senha temporária</span></div></div><div class="tablewrap"><table class="responsive-table"><thead><tr><th>Usuário</th><th>Perfil</th><th>Situação</th><th>Senha</th><th></th></tr></thead><tbody>${platformUsers.map(user=>`<tr><td><b>${esc(user.displayName)}</b><span class="sub">${esc(user.email)}</span></td><td>${esc(roleLabel(user.role))}</td><td>${badge(user.active?'Ativo':'Inativo')}</td><td>${user.mustChangePassword?'<span class="badge amber">Troca pendente</span>':'<span class="badge">Definida</span>'}</td><td><button onclick="editPlatformUser('${esc(user.id)}')">Editar</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum usuário cadastrado.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panelhead"><div><h2>Recursos cadastrados</h2><span class="sub">${activeProjectResources.length} recursos ativos · entidade ${esc(glpiProjectDirectory.entity)}</span></div></div><div class="tablewrap"><table class="responsive-table"><thead><tr><th>Recurso</th><th>Login GLPI</th><th>Localização</th><th>Responsável</th><th>Situação</th><th>Uso</th></tr></thead><tbody>${glpiProjectDirectory.users.map(user=>`<tr><td><b>${esc(user.displayName)}</b><span class="sub">${esc(user.email)}</span></td><td>${esc(user.login)}</td><td>${esc(user.location||'Não informada')}</td><td>${esc(user.supervisorName||user.supervisorLogin||'Não informado')}</td><td>${badge(user.active===false?'Inativo':'Ativo')}</td><td><span class="badge blue">Recurso de projeto</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum recurso cadastrado.</td></tr>'}</tbody></table></div></section>`}
function projectTypeAdministration(){return `<section class="panel"><div class="panelhead"><div><h2>Tipos de projeto</h2><span class="sub">Cadastro central usado nas demandas de viabilidade e nos projetos</span></div><button onclick="editProjectType()">+ Novo tipo</button></div><div class="tablewrap"><table class="responsive-table"><thead><tr><th>Ordem</th><th>Tipo</th><th>Descrição</th><th>Situação</th><th></th></tr></thead><tbody>${projectTypes.map(type=>`<tr><td>${type.sequence}</td><td><b>${esc(type.name)}</b></td><td>${esc(type.description||'')}</td><td>${badge(type.active===false?'Inativo':'Ativo')}</td><td><button onclick="editProjectType(${type.id})">Editar</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum tipo de projeto cadastrado.</td></tr>'}</tbody></table></div></section>`}
function editProjectType(id){const type=projectTypes.find(item=>Number(item.id)===Number(id))||{name:'',description:'',sequence:(projectTypes.length+1)*10,active:true};modal(id?'Editar tipo de projeto':'Novo tipo de projeto',`<form onsubmit="saveProjectType(event,${id||0})"><div class="formgrid"><label>Nome<input name="name" required maxlength="120" value="${esc(type.name)}" placeholder="Ex.: Automação"></label><label>Ordem<input name="sequence" type="number" min="0" step="10" required value="${type.sequence}"></label><label class="wide">Descrição<textarea name="description" maxlength="400" placeholder="Quando este tipo deve ser utilizado">${esc(type.description||'')}</textarea></label><label>Situação<select name="active"><option value="true" ${type.active!==false?'selected':''}>Ativo</option><option value="false" ${type.active===false?'selected':''}>Inativo</option></select></label></div><div class="toolbar"><button type="button" onclick="this.closest('dialog').close()">Cancelar</button><button class="primary" type="submit">Salvar tipo</button></div></form>`)}
async function saveProjectType(event,id){event.preventDefault();const form=Object.fromEntries(new FormData(event.target)),payload={id,name:form.name,description:form.description,sequence:Number(form.sequence),active:form.active==='true'},response=await fetch('/api/project-types',{method:id?'PATCH':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),result=await response.json();if(!response.ok){toast(result.error||'Não foi possível salvar o tipo de projeto.');return}if(id){const index=projectTypes.findIndex(item=>Number(item.id)===Number(id));projectTypes[index]=result.projectType}else projectTypes.push(result.projectType);projectTypes.sort((a,b)=>a.sequence-b.sequence||a.name.localeCompare(b.name,'pt-BR'));$('dialog').close();render();toast('Tipo de projeto salvo e disponível nos cadastros.')}
function editPlatformUser(id){const user=platformUsers.find(item=>item.id===id)||{displayName:'',email:'',role:'keyuser',active:true};modal(id?'Editar usuário':'Novo usuário',`<form onsubmit="savePlatformUser(event,'${id||''}')"><div class="formgrid"><label>Nome completo<input name="displayName" required value="${esc(user.displayName)}"></label><label>E-mail corporativo<input name="email" type="email" required value="${esc(user.email)}" ${id?'readonly':''}></label><label>Perfil<select name="role">${['project_coordinator','it_director','project_analyst','keyuser','requester','area_manager','viewer'].map(role=>`<option value="${role}" ${role===user.role?'selected':''}>${esc(roleLabel(role))}</option>`).join('')}</select></label><label>Conta<select name="active"><option value="true" ${user.active?'selected':''}>Ativa</option><option value="false" ${!user.active?'selected':''}>Inativa</option></select></label><label class="wide">${id?'Nova senha temporária (opcional)':'Senha temporária'}<input name="password" type="password" minlength="10" ${id?'':'required'} autocomplete="new-password" placeholder="Mínimo de 10 caracteres"></label></div><p class="muted">A senha deve conter letra maiúscula, minúscula e número. O usuário deverá alterá-la no primeiro acesso.</p><div class="toolbar"><button class="primary" type="submit">Salvar usuário</button></div></form>`)}
async function savePlatformUser(event,id){event.preventDefault();const form=Object.fromEntries(new FormData(event.target));const payload={id,displayName:form.displayName,email:form.email,role:form.role,active:form.active==='true',password:form.password};const response=await fetch('/api/users',{method:id?'PATCH':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok){toast(result.error||'Não foi possível salvar o usuário.');return}if(id){const index=platformUsers.findIndex(item=>item.id===id);platformUsers[index]=result.user}else platformUsers.push(result.user);$('dialog').close();render();toast('Usuário salvo com acesso por e-mail e senha.')}
function editTask(id){let t=tasks.find(t=>t.id===id)||{name:'',p:+kanbanProject||selected,person:3,state:0,plan:8,actual:0,sprint:1,delivery:'Entrega',start:40,end:50};modal(id?'Editar atividade':'Nova atividade',`<form onsubmit="saveTask(event,${id||0})"><div class="formgrid"><label class="wide">Atividade<input name="name" required value="${esc(t.name)}"></label><label>Projeto<select name="p">${projects.map(p=>`<option value="${p.id}" ${p.id===t.p?'selected':''}>${p.name}</option>`).join('')}</select></label><label>Responsável<select name="person">${people.map((p,i)=>`<option value="${i}" ${i===t.person?'selected':''}>${p}</option>`).join('')}</select></label><label>Horas planejadas<input name="plan" type="number" min="0" required value="${t.plan}"></label><label>Horas realizadas em projetos<input name="actual" type="number" min="0" required value="${t.actual}"></label><label>Sprint<input name="sprint" type="number" min="1" required value="${t.sprint}"></label><label>Fase / entrega<input name="delivery" required value="${esc(t.delivery)}"></label></div><p class="muted">Alterações valem apenas nesta sessão demonstrativa.</p><div class="toolbar"><button class="primary" type="submit">Salvar atividade</button></div></form>`)}
function saveTask(e,id){e.preventDefault();let f=new FormData(e.target),values=Object.fromEntries(f);for(let k of ['p','person','plan','actual','sprint'])values[k]=+values[k];if(id)Object.assign(tasks.find(t=>t.id===id),values);else tasks.push({id:Math.max(...tasks.map(t=>t.id))+1,...values,state:0,start:40,end:50});$('dialog').close();render();toast('Atividade salva nesta sessão.')} 
function demandReference(d){return d.source==='platform'?`Plataforma #DMD-${String(d.id).padStart(4,'0')}`:`GLPI #${esc(d.externalId||d.id)}`}
function demandStatusLabel(d){return d.source==='glpi'&&d.sourceStatus?d.sourceStatus:d.stage}
function setDemandSources(values){demandSources=values;render()}
function setDemandStatuses(values){demandStatuses=values;render()}
function setDemandTypes(values){demandTypes=values.map(String);render()}
function demandOpenedLabel(value){return value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'Não informada'}
function filteredDemands(){const query=demandQuery.trim().toLowerCase();return demands.filter(d=>(!demandSources.length||demandSources.includes(d.source))&&(!demandStatuses.length||demandStatuses.includes(demandStatusLabel(d)))&&(!demandTypes.length||demandTypes.includes(String(d.projectTypeId||'')))&&(!query||`${d.name} ${d.externalId} ${d.area} ${d.requesterName}`.toLowerCase().includes(query)))}
const requirementKeys=['company','directorate','processOwner','demandType','currentProcess','scope','expectedProcess','businessRules','acceptanceCriteria','automationDetails','reportDetails','integrationDetails','systemChangeDetails','newSolutionDetails','otherDemandDetails','benefitType','dataAvailability','monthlyExecutions','minutesPerExecution','volumeSource','missingData','volumeNotApplicableReason','reworkStatus','reworkDetails','reworkContact','hasRequiredDate','requiredDate','requiredDateReason','evidenceAvailability','evidenceExplanation'];
function requirementOptions(options,selected,placeholder='Selecione'){return `<option value="">${placeholder}</option>${options.map(option=>`<option ${option===selected?'selected':''}>${esc(option)}</option>`).join('')}`}
function requirementConditional(field,values,current,label,name,help,type='textarea'){const visible=values.includes(current),inputType=name==='requiredDate'?'date':['monthlyExecutions','minutesPerExecution'].includes(name)?'number':'text',numberRules=inputType==='number'?` min="${name==='monthlyExecutions'?1:0.01}" step="${name==='monthlyExecutions'?1:0.01}"`:'',control=type==='input'?`<input name="${name}" type="${inputType}"${numberRules} value="${esc(currentDemandValue(name))}" ${visible?'required':'disabled'} data-required="true">`:`<textarea name="${name}" ${visible?'required':'disabled'} data-required="true" placeholder="${esc(help)}">${esc(currentDemandValue(name))}</textarea>`;return `<div class="conditional-fields wide" data-condition-field="${field}" data-condition-values="${esc(values.join('|'))}" ${visible?'':'hidden'}><label>${label}${control}<small>${esc(help)}</small></label></div>`}
let renderingDemand=null;
function currentDemandValue(name){return renderingDemand?.[name]||''}
function demandRequirementsForm(d){renderingDemand=d;const demandTypes=['Automação','Relatório ou painel','Integração','Alteração de sistema','Novo processo ou solução','Outro'],benefitTypes=['Liberar tempo da equipe','Reduzir erros ou retrabalho','Reduzir desembolsos','Aumentar capacidade ou receita','Atender obrigação ou reduzir risco','Outro'],dataOptions=['Sim, medidos','Sim, estimados','Tenho apenas parte dos dados','Ainda não tenho','Não se aplica — processo novo ou benefício de outra natureza'],reworkOptions=['Sim','Não','Ainda não sabemos','Não se aplica'],evidenceOptions=['Sim','Não disponível no momento','Não se aplica'];const html=`
<div class="requirements-intro"><b>Levantamento de requisitos</b><p>Descreva o problema e como o processo funciona hoje. Use exemplos reais e indique quando os números forem estimados. Não é necessário definir a solução técnica ou calcular o ROI.</p></div>
<details class="requirement-block" open><summary><span>A</span><div><b>Identificação e contexto</b><small>Dados básicos, responsáveis e classificação</small></div></summary><div class="requirement-content formgrid"><label class="wide">Título da solicitação<input value="${esc(d.name)}" readonly></label><label>Categoria<input value="${esc(d.sourceCategory||'Projeto > Estudo de Viabilidade')}" readonly></label><label>Urgência / impacto<select name="impact" required>${['Baixo','Médio','Alto'].map(i=>`<option ${d.impact===i?'selected':''}>${i}</option>`).join('')}</select><small>Impacto e prazo serão considerados na priorização.</small></label><label>Empresa<input name="company" value="${esc(d.company||'')}" placeholder="Informe a empresa"></label><label>Diretoria<input name="directorate" value="${esc(d.directorate||d.area||'')}" placeholder="Informe a diretoria"></label><label class="wide">Responsável pelo processo e responsável pela validação<textarea name="processOwner" required placeholder="Nome, área e contato de cada responsável; pode ser a mesma pessoa.">${esc(d.processOwner||'')}</textarea></label><label>Tipo principal da demanda<select name="demandType" required onchange="updateRequirementVisibility(this.form)">${requirementOptions(demandTypes,d.demandType)}</select><small>Selecione o objetivo predominante.</small></label><label>Tipo de projeto<select name="projectTypeId" required>${projectTypeOptions(d.projectTypeId)}</select></label></div></details>
<details class="requirement-block" open><summary><span>B</span><div><b>Problema e processo atual</b><small>Cenário, impacto e escopo</small></div></summary><div class="requirement-content formgrid"><label class="wide">Problema a resolver e consequência de mantê-lo<textarea name="objective" required placeholder="Inclua um caso real, as áreas afetadas e o impacto.">${esc(d.objective)}</textarea></label><label class="wide">Como o trabalho é realizado hoje?<textarea name="currentProcess" required placeholder="Descreva início, etapas, responsáveis, sistemas ou planilhas e resultado final.">${esc(d.currentProcess||'')}</textarea></label><label class="wide">Quem será atendido e o que está no escopo?<textarea name="scope" required placeholder="Informe usuários, empresas, unidades ou áreas e o que ficará fora da solicitação.">${esc(d.scope||'')}</textarea></label></div></details>
<details class="requirement-block"><summary><span>C</span><div><b>Resultado esperado e requisitos</b><small>Funcionamento, regras e critérios de aceite</small></div></summary><div class="requirement-content formgrid"><label class="wide">Como o processo deverá funcionar após a entrega?<textarea name="expectedProcess" required placeholder="Explique entradas, ações e saídas esperadas, sem necessidade de linguagem técnica.">${esc(d.expectedProcess||'')}</textarea></label><label class="wide">Regras, exceções e restrições<textarea name="businessRules" required placeholder="Ex.: aprovação por valor, duplicidades, perfis de acesso, dados obrigatórios e exceções.">${esc(d.businessRules||'')}</textarea></label><label class="wide">Situações que deverão ser testadas para aprovar a entrega<textarea name="acceptanceCriteria" required placeholder="Liste situação, ação e resultado esperado; inclua ao menos um caso representativo.">${esc(d.acceptanceCriteria||'')}</textarea></label>${requirementConditional('demandType',['Automação'],d.demandType,'Detalhes da automação','automationDetails','Etapas repetitivas, gatilho, frequência e decisões humanas.')}${requirementConditional('demandType',['Relatório ou painel'],d.demandType,'Detalhes do relatório ou painel','reportDetails','Indicadores, regras de cálculo, fontes, filtros, atualização e público.')}${requirementConditional('demandType',['Integração'],d.demandType,'Detalhes da integração','integrationDetails','Sistemas, informações trocadas, momento da troca e tratamento de falhas.')}${requirementConditional('demandType',['Alteração de sistema'],d.demandType,'Detalhes da alteração de sistema','systemChangeDetails','Sistema, tela ou rotina, comportamento atual e comportamento esperado.')}${requirementConditional('demandType',['Novo processo ou solução'],d.demandType,'Detalhes do novo processo ou solução','newSolutionDetails','Evento inicial, participantes, aprovações e entrega que encerra o processo.')}${requirementConditional('demandType',['Outro'],d.demandType,'Detalhes do tipo de demanda','otherDemandDetails','Explique a natureza da demanda e os requisitos específicos.')}</div></details>
<details class="requirement-block"><summary><span>D</span><div><b>Dados para avaliar os benefícios</b><small>Indicadores, volumes, tempos e retrabalho</small></div></summary><div class="requirement-content formgrid"><label>Benefício principal esperado<select name="benefitType" required>${requirementOptions(benefitTypes,d.benefitType)}</select></label><label class="wide">Como perceberemos ou mediremos esse benefício?<textarea name="benefit" required placeholder="Informe o indicador atual e o resultado desejado, se conhecidos.">${esc(d.benefit)}</textarea></label><label>Disponibilidade de dados de volume e tempo<select name="dataAvailability" required onchange="updateRequirementVisibility(this.form)">${requirementOptions(dataOptions,d.dataAvailability)}</select></label>${requirementConditional('dataAvailability',['Sim, medidos','Sim, estimados'],d.dataAvailability,'Execuções em um mês típico','monthlyExecutions','Informe o volume total do processo.','input')}${requirementConditional('dataAvailability',['Sim, medidos','Sim, estimados'],d.dataAvailability,'Minutos de trabalho por execução','minutesPerExecution','Some o trabalho das pessoas; não inclua espera sem trabalho.','input')}${requirementConditional('dataAvailability',['Sim, medidos','Sim, estimados'],d.dataAvailability,'Origem dos números e período de referência','volumeSource','Informe relatório, amostra ou responsável, período e sazonalidade.')}${requirementConditional('dataAvailability',['Tenho apenas parte dos dados','Ainda não tenho'],d.dataAvailability,'Dados existentes, pendências e responsável','missingData','Informe valores conhecidos, unidade, responsável e previsão de levantamento.')}${requirementConditional('dataAvailability',['Não se aplica — processo novo ou benefício de outra natureza'],d.dataAvailability,'Por que volume e tempo não se aplicam?','volumeNotApplicableReason','Explique como a viabilidade poderá ser avaliada e quais evidências usar.')}
<label>Existe erro ou retrabalho?<select name="reworkStatus" required onchange="updateRequirementVisibility(this.form)">${requirementOptions(reworkOptions,d.reworkStatus)}</select></label>${requirementConditional('reworkStatus',['Sim'],d.reworkStatus,'Como ocorre o retrabalho e qual seu impacto?','reworkDetails','Informe casos por mês, tempo de correção e origem dos dados.')}${requirementConditional('reworkStatus',['Ainda não sabemos'],d.reworkStatus,'Quem pode confirmar se há retrabalho?','reworkContact','Informe o responsável e como verificar.','input')}</div></details>
<details class="requirement-block"><summary><span>E</span><div><b>Prazo e evidências</b><small>Datas necessárias, justificativas e anexos</small></div></summary><div class="requirement-content formgrid"><label>Existe uma data necessária para entrega?<select name="hasRequiredDate" required onchange="updateRequirementVisibility(this.form)">${requirementOptions(['Sim','Não'],d.hasRequiredDate)}</select></label>${requirementConditional('hasRequiredDate',['Sim'],d.hasRequiredDate,'Data necessária','requiredDate','Informe a data necessária.','input')}${requirementConditional('hasRequiredDate',['Sim'],d.hasRequiredDate,'O que determina essa data?','requiredDateReason','Diferencie compromisso externo, dependência operacional e preferência.')}
<label>Há evidência ou exemplo que possa ser anexado?<select name="evidenceAvailability" required onchange="updateRequirementVisibility(this.form)">${requirementOptions(evidenceOptions,d.evidenceAvailability)}</select></label><div class="conditional-fields wide evidence-upload" data-condition-field="evidenceAvailability" data-condition-values="Sim" ${d.evidenceAvailability==='Sim'?'':'hidden'}><div class="notice mini"><b>Anexos:</b> ${d.source==='glpi'?'consulte os arquivos vinculados ao ticket de origem no GLPI.':'o envio de arquivos será habilitado em uma próxima etapa; registre abaixo onde a evidência está disponível.'}</div></div>${requirementConditional('evidenceAvailability',['Não disponível no momento','Não se aplica','Sim'],d.evidenceAvailability,'Onde a evidência pode ser consultada ou por que não está disponível?','evidenceExplanation','Indique local, responsável pelo acesso ou justificativa.')}</div></details>
<details class="requirement-block"><summary><span>F</span><div><b>Análise técnica e viabilidade</b><small>Preenchimento da equipe de Projetos e TI</small></div></summary><div class="requirement-content formgrid"><label class="wide">Solução proposta<textarea name="solution" required>${esc(d.solution)}</textarea></label><label class="wide">Riscos e dependências<textarea name="risk" required>${esc(d.risk)}</textarea></label><label>Custo estimado (R$)<input name="cost" type="number" min="0" required value="${d.cost}"></label><label>Esforço estimado (horas)<input name="hours" type="number" min="1" required value="${d.hours}"></label><label>Projeto priorizado?<select name="projectPrioritized" onchange="toggleDemandPrioritization(this)"><option value="false" ${!d.projectPrioritized?'selected':''}>Não</option><option value="true" ${d.projectPrioritized?'selected':''}>Sim</option></select></label><label>Data da priorização<input id="demand-prioritization-date" name="prioritizationDate" type="date" value="${esc(d.prioritizationDate||'')}" ${d.projectPrioritized?'required':'disabled'}></label><label>Diretor que aprovou<input id="demand-approving-director" name="approvingDirector" value="${esc(d.approvingDirector||'')}" maxlength="160" ${d.projectPrioritized?'required':'disabled'} placeholder="Nome do diretor"></label><label>Responsável pela análise<input value="Analista de Projetos 1" readonly></label></div></details>`;renderingDemand=null;return html}
function updateRequirementVisibility(form){form.querySelectorAll('[data-condition-field]').forEach(block=>{const field=form.elements[block.dataset.conditionField],values=(block.dataset.conditionValues||'').split('|'),visible=values.includes(field?.value||'');block.hidden=!visible;block.querySelectorAll('[data-required]').forEach(control=>{control.disabled=!visible;control.required=visible})})}
function demandRequirementsPayload(values){return Object.fromEntries(requirementKeys.map(key=>[key,String(values[key]||'').trim()]))}
function selectDemand(id){activeDemand=Number(id);render()}function demandas(){const d=demands.find(item=>item.id===activeDemand)||demands[0];if(!d)return heading('Demandas e viabilidade','Da solicitação ao estudo que fundamenta a decisão.',`<button class="primary" onclick="editNewDemand()">+ Nova demanda</button>`)+`<section class="panel empty">Nenhuma demanda disponível.</section>`;activeDemand=d.id;const demandOptions=demands.map(item=>`<option value="${item.id}" ${item.id===d.id?'selected':''}>${esc(demandReference(item))} · ${esc(item.name)} · ${esc(demandStatusLabel(item))}</option>`).join(''),glpiInfo=d.source==='glpi'?`<div class="notice demand-origin"><b>Ticket recebido do GLPI</b><span><strong>Entidade:</strong> ${esc(d.sourceEntity||'Projeto')}</span><span><strong>Categoria:</strong> ${esc(d.sourceCategory||'Estudo de Viabilidade')}</span><span><strong>Status GLPI:</strong> ${esc(d.sourceStatus||'Não informado')}</span><span><strong>Abertura:</strong> ${demandOpenedLabel(d.sourceOpenedAt)}</span></div>`:'';return heading('Demandas e viabilidade','Selecione uma demanda para consultar ou preencher o levantamento de requisitos.',`<button class="primary" onclick="editNewDemand()">+ Nova demanda</button>`)+`<section class="panel demand-selector"><div><span class="eyebrow">DEMANDA SELECIONADA</span><label><select aria-label="Selecionar demanda" onchange="selectDemand(this.value)">${demandOptions}</select></label></div><div class="demand-selector-meta">${badge(d.stage)}${projectTypeBadge(d)}<span>${esc(d.area)}</span><span>${esc(d.requesterName||'Solicitante não informado')}</span></div></section><section class="panel demand-detail demand-detail-full"><div class="panelhead"><div><h2>${esc(d.name)}</h2><span class="sub">${demandReference(d)} · ${esc(d.area)} · ${esc(d.requesterName||'Solicitante não informado')}</span></div>${badge(d.stage)}</div><form class="pad" onsubmit="saveDemand(event,${d.id})">${glpiInfo}${demandRequirementsForm(d)}<div class="toolbar demand-actions" style="margin-top:22px"><button type="submit" ${['Aprovações','Aprovada','Convertida','Rejeitada'].includes(d.stage)?'disabled':''}>Salvar estudo</button><button type="button" class="primary" onclick="sendApproval(${d.id})" ${d.stage!=='Estudo de viabilidade'?'disabled':''}>Enviar para aprovação →</button></div><p class="muted">Salvar o estudo encaminha a demanda para a etapa Estudo de viabilidade e prepara o envio à estrutura fixa de aprovação.</p></form></section>`}
function toggleDemandPrioritization(select){const prioritized=select.value==='true',form=select.closest('form');['#demand-prioritization-date','#demand-approving-director'].forEach(selector=>{const field=form.querySelector(selector);field.disabled=!prioritized;field.required=prioritized;if(!prioritized)field.value=''})}
function editNewDemand(){modal('Nova demanda',`<form onsubmit="saveNewDemand(event)"><div class="formgrid"><label class="wide">Título da demanda<input name="name" required maxlength="180" placeholder="Ex.: Automatizar conferência de documentos"></label><label>Área solicitante<input name="area" required maxlength="120" placeholder="Ex.: Controladoria"></label><label>Tipo de projeto<select name="projectTypeId" required>${projectTypeOptions('')}</select></label><label>Impacto<select name="impact"><option>Baixo</option><option selected>Médio</option><option>Alto</option></select></label><label class="wide">Problema ou necessidade<textarea name="objective" required maxlength="1200" placeholder="Descreva o cenário atual e o que precisa ser resolvido."></textarea></label><label class="wide">Benefício esperado<textarea name="benefit" required maxlength="1200" placeholder="Descreva o resultado esperado para a área."></textarea></label><label>Solução proposta (opcional)<textarea name="solution" maxlength="1200" placeholder="Pode ser detalhada durante o estudo."></textarea></label><label>Riscos ou dependências (opcional)<textarea name="risk" maxlength="1200" placeholder="Ex.: integração, fornecedor ou prazo legal."></textarea></label></div><div class="notice mini">Solicitante: <b>${esc(currentIdentity.displayName)}</b> · A demanda será criada na etapa <b>Triagem</b>.</div><div class="toolbar"><button type="button" onclick="this.closest('dialog').close()">Cancelar</button><button class="primary" type="submit">Cadastrar demanda</button></div></form>`)}
async function saveNewDemand(event){event.preventDefault();const button=event.submitter;button.disabled=true;const payload=Object.fromEntries(new FormData(event.target));const response=await fetch('/api/demands',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),result=await response.json();if(!response.ok){button.disabled=false;toast(result.error||'Não foi possível cadastrar a demanda.');return}const demand=normalizePlatformDemand(result.demand);demands.unshift(demand);activeDemand=demand.id;$('dialog').close();render();toast('Demanda cadastrada e encaminhada para triagem.')}
async function saveDemand(e,id){e.preventDefault();let d=demands.find(d=>d.id===id);if(['Aprovações','Aprovada','Convertida','Rejeitada'].includes(d.stage))return;const values=Object.fromEntries(new FormData(e.target)),requirements=demandRequirementsPayload(values);values.projectPrioritized=values.projectPrioritized==='true';values.prioritizationDate=values.projectPrioritized?values.prioritizationDate||'':'';values.approvingDirector=values.projectPrioritized?String(values.approvingDirector||'').trim():'';if(values.projectPrioritized&&(!values.prioritizationDate||!values.approvingDirector)){toast('Informe a data da priorização e o diretor que aprovou.');return}Object.assign(d,values,requirements,{requirements});d.cost=+d.cost;d.hours=+d.hours;d.stage='Estudo de viabilidade';if(d.persisted){const response=await fetch('/api/demands',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({id:d.id,...values,requirements,cost:d.cost,hours:d.hours,stage:d.stage})}),result=await response.json();if(!response.ok){toast(result.error||'Não foi possível salvar o estudo.');return}Object.assign(d,normalizePlatformDemand(result.demand))}render();toast('Levantamento e estudo de viabilidade salvos.')}
function sendApproval(id){let d=demands.find(d=>d.id===id);d.stage='Aprovações';d.step=0;view='aprovacoes';activeDemand=id;render()}
function aprovacoes(){return heading('Central de aprovações','Quatro decisões obrigatórias, sempre na mesma sequência.')+`<div class="notice">Simulação do fluxo: você pode testar as decisões de cada perfil. No sistema definitivo, cada etapa exigirá o usuário autorizado.</div>${demands.map(d=>`<section class="panel pad"><div class="heading" style="margin-bottom:0"><div><h2>${esc(d.name)}</h2><p class="muted">${demandReference(d)} · ${projectTypeName(d.projectTypeId)} · ${money(d.cost)} · ${d.hours}h · Impacto ${d.impact.toLowerCase()}</p><p class="mini"><b>Projeto priorizado:</b> ${d.projectPrioritized?'Sim · '+formatDate(d.prioritizationDate)+' · '+esc(d.approvingDirector):'Não'}</p></div>${badge(d.stage)}</div><div class="steps">${roles.map((r,i)=>`<div class="step ${d.stage==='Aprovações'&&i===d.step?'current':''}"><span class="muted">ETAPA ${i+1}</span><b>${r}</b>${badge(i<d.step?'Aprovado':i===d.step&&d.stage==='Aprovações'?'Aguardando decisão':'Pendente')}</div>`).join('')}</div><div class="toolbar"><button onclick="activeDemand=${d.id};nav('demandas')">Consultar estudo</button>${d.stage==='Aprovações'?`<button class="primary" onclick="decide(${d.id},'Aprovado')">Aprovar etapa ${d.step+1}</button><button onclick="decide(${d.id},'Complementação')">Solicitar complementação</button><button onclick="decide(${d.id},'Rejeitado')">Rejeitar</button>`:d.stage==='Aprovada'?`<button class="primary" onclick="convertDemand(${d.id})">Definir projeto ou tarefa</button>`:''}</div>${d.history.length?`<details style="margin-top:20px"><summary>Histórico de decisões (${d.history.length})</summary>${d.history.map(h=>`<p class="mini">${esc(h.date)} · ${esc(h.role)} · <b>${esc(h.decision)}</b><br>${esc(h.note)}</p>`).join('')}</details>`:''}</section>`).join('')}`}
function decide(id,decision){modal(decision==='Aprovado'?'Registrar aprovação':'Registrar decisão',`<form onsubmit="confirmDecision(event,${id},'${decision}')"><label>Justificativa<textarea name="note" ${decision!=='Aprovado'?'required':''} placeholder="Registre sua avaliação"></textarea></label><div class="toolbar"><button class="primary" type="submit">Confirmar ${decision==='Aprovado'?'aprovação':'decisão'}</button></div></form>`)}function confirmDecision(e,id,decision){e.preventDefault();let d=demands.find(d=>d.id===id);d.history.push({role:roles[d.step],decision,note:new FormData(e.target).get('note')||'Sem observações.',date:new Date().toLocaleString('pt-BR')});if(decision==='Aprovado'){d.step++;if(d.step===4)d.stage='Aprovada'}else if(decision==='Complementação'){d.stage='Estudo de viabilidade';d.step=0}else d.stage='Rejeitada';$('dialog').close();render();toast('Decisão registrada no histórico demonstrativo.')}function convertDemand(id){modal('Encaminhar demanda aprovada',`<form onsubmit="confirmConvert(event,${id})"><div class="formgrid"><label>Classificação<select name="kind"><option>Projeto</option><option>Tarefa</option></select></label><label>Projeto de destino (para tarefa)<select name="project">${projects.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label></div><div class="toolbar"><button class="primary">Criar e planejar</button></div></form>`)}async function confirmConvert(e,id){e.preventDefault();let d=demands.find(d=>d.id===id),f=new FormData(e.target);if(f.get('kind')==='Projeto'){const response=await fetch('/api/projects',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:d.name,projectTypeId:d.projectTypeId,area:d.area,status:'planning',plannedHours:d.hours,plannedCost:d.cost,projectPrioritized:d.projectPrioritized,prioritizationDate:d.prioritizationDate,approvingDirector:d.approvingDirector})}),result=await response.json();if(!response.ok){toast(result.error||'Não foi possível criar o projeto.');return}let pid=500000+result.project.id;projects.push({id:pid,dbId:result.project.id,name:d.name,projectTypeId:d.projectTypeId,type:projectTypeName(d.projectTypeId),area:d.area,owner:1,status:'Em planejamento',risk:'Dentro do Prazo',start:45,end:95,plan:d.hours,cost:d.cost,spent:0,source:'Plataforma',projectPrioritized:d.projectPrioritized,prioritizationDate:d.prioritizationDate,approvingDirector:d.approvingDirector});selected=pid;view='portfolio'}else{tasks.push({id:Math.max(...tasks.map(t=>t.id))+1,p:+f.get('project'),name:d.name,person:1,state:0,plan:d.hours,actual:0,start:45,end:60,sprint:1,delivery:'Planejamento'});view='kanban';kanbanProject=f.get('project')}d.stage='Convertida';$('dialog').close();render();toast('Demanda encaminhada para planejamento.')}
function comparativo(){let planned=projects.reduce((s,p)=>s+p.plan,0),actual=tasks.reduce((s,t)=>s+t.actual,0),duration=value=>typeof workedTimeLabel==='function'?workedTimeLabel(value):timeNumber(value)+'h';return heading('Planejado × Realizado','Linha de base aprovada e consumo realizado até o momento.',`<button onclick="exportReport()">↓ Exportar relatório CSV</button>`)+`<div class="stats">${stat('Esforço planejado',planned+'h','Linha de base dos projetos')}${stat('Esforço realizado',duration(actual),'Apontamentos das atividades · hh:mm:ss')}${stat('Orçamento aprovado',money(projects.reduce((a,p)=>a+p.cost,0)),'Total da carteira')}${stat('Custo realizado',money(projects.reduce((a,p)=>a+p.spent,0)),'Valores demonstrativos')}</div><section class="panel"><div class="panelhead"><h2>Acompanhamento por projeto</h2></div><div class="tablewrap"><table class="responsive-table"><thead><tr><th>Projeto</th><th>Base de esforço</th><th>Realizado</th><th>Saldo de esforço</th><th>Orçado / realizado</th><th>Prazo</th></tr></thead><tbody>${projects.map(p=>`<tr><td><button class="projecttitle" onclick="openProject(${p.id})">${p.name}</button><span class="sub">Progresso por status: ${progress(p.id)}%</span></td><td>${p.plan}h</td><td>${duration(hours(p.id))}</td><td>${timeNumber(p.plan-hours(p.id))}h</td><td>${money(p.cost)}<span class="sub">${money(p.spent)}</span></td><td>${badge(p.risk)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panelhead"><h2>Desvios nas atividades concluídas</h2><span class="muted">Realizado − planejado</span></div>${tasks.filter(t=>t.state===3).map(t=>`<div class="row"><div>${esc(t.name)}<span class="sub">${t.plan}h planejadas · ${duration(t.actual)} realizadas</span></div><b class="${t.actual>t.plan?'danger':''}">${t.actual-t.plan>0?'+':''}${timeNumber(t.actual-t.plan)}h</b></div>`).join('')||'<p class="empty">Nenhuma atividade concluída.</p>'}</section><p class="muted">Saldo representa horas ainda não consumidas; não é uma previsão de esforço restante. O progresso demonstrativo é calculado pelo status das atividades.</p>`}
function exportReport(){let csv='\ufeffProjeto;Área;Horas planejadas;Horas realizadas;Custo planejado;Custo realizado\r\n'+projects.map(p=>[p.name,p.area,p.plan,hours(p.id),p.cost,p.spent].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='planejado-realizado-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const allocations=[{project:24,support:0},{project:32,support:0},{project:36,support:0},{project:20,support:16},{project:24,support:20},{project:16,support:20},{project:20,support:16},{project:12,support:16}];
function recursos(){let all=allocations.reduce((a,r)=>a+r.project+r.support,0);return heading('Gestão de tempo e recursos','Projetos e sustentação na mesma visão de capacidade.')+`<div class="stats">${stat('Equipe',8,'1 coordenador · 2 analistas · 5 keyusers')}${stat('Capacidade semanal','320h','Premissa demonstrativa: 40h por pessoa')}${stat('Alocação prevista',all+'h','Projetos + reserva de sustentação')}${stat('Acima da capacidade',allocations.filter(r=>r.project+r.support>40).length,'Profissionais que exigem ajuste')}</div><section class="panel"><div class="panelhead"><h2>Distribuição da capacidade</h2><span class="badge">14–18 set. 2026</span></div><div class="tablewrap"><table class="responsive-table"><thead><tr><th>Profissional</th><th>Distribuição prevista</th><th>Projetos</th><th>Reserva sustentação</th><th>Saldo semanal</th></tr></thead><tbody>${people.map((p,i)=>{let a=allocations[i],sum=a.project+a.support;return `<tr><td><b>${p}</b><span class="sub">Capacidade: 40h / semana</span></td><td style="min-width:180px"><div class="capacity"><i style="width:${a.project/Math.max(40,sum)*100}%"></i><b style="width:${a.support/Math.max(40,sum)*100}%"></b></div></td><td>${a.project}h</td><td>${a.support}h</td><td>${sum>40?'<span class="badge red">Sobrecarga: '+(sum-40)+'h</span>':(40-sum)+'h disponíveis'}</td></tr>`}).join('')}</tbody></table></div><div class="pad"><div class="legend"><span>Projetos</span><span>Sustentação</span><span>Disponível</span></div></div></section><div class="split"><section class="panel"><div class="panelhead"><h2>Sustentação realizada · GLPI</h2><span class="badge amber">Simulação</span></div>${[18,23,16,14,15].map((h,i)=>`<div class="row"><span>Keyuser ${i+1}</span><span>${h}h apontadas nesta semana</span></div>`).join('')}</section><section class="panel pad"><h2>Planejar com capacidade real</h2><p class="muted">Os chamados de sustentação continuam sendo executados no GLPI. Seus apontamentos comporão o esforço realizado, sem digitação em duplicidade.</p><p class="muted">A reserva é uma previsão para planejar projetos. O realizado permite revisar essa previsão a cada período.</p><div class="notice">Keyuser 2: 44h previstas para 40h disponíveis. Realoque 4h ou revise o compromisso da semana.</div></section></div>`}
