document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileMenuOpen)toggleMobileMenu(false)});
window.addEventListener('resize',()=>{if(window.innerWidth>900&&mobileMenuOpen)toggleMobileMenu(false)},{passive:true});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'update_demo_task_status',description:'Altera o status de uma atividade fictícia nesta sessão e atualiza Kanban, Gantt e portfólio.',inputSchema:{type:'object',properties:{taskId:{type:'integer'},status:{type:'integer',minimum:0,maximum:3}},required:['taskId','status'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||!Number.isInteger(input.taskId)||!Number.isInteger(input.status)||input.status<0||input.status>3||!tasks.some(t=>t.id===input.taskId))throw new Error('Atividade ou status inválido.');moveTask(input.taskId,input.status);return {taskId:input.taskId,status:states[input.status],scope:'sessão demonstrativa'};}})).catch(()=>{});}catch{}}


